#include <iostream>
#include <string>
#include <vector>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int T;
    if (!(std::cin >> T)) return 0;

    std::vector<std::string> answers;
    answers.reserve(T);

    for (int i = 0; i < T; ++i) {
        std::string s;
        std::cin >> s;

        int balance = 0;
        bool valid = true;

        for (char ch : s) {
            if (ch == '(') {
                ++balance;
            } else {
                --balance;
            }

            if (balance < 0) {
                valid = false;
                break;
            }
        }

        if (balance != 0) {
            valid = false;
        }

        answers.push_back(valid ? "YES" : "NO");
    }

    for (const std::string& answer : answers) {
        std::cout << answer << '\n';
    }

    return 0;
}
